import fs from 'node:fs';import http from 'node:http';import path from 'node:path';import assert from 'node:assert/strict';import {hash,json} from './seal-simple-website-successor.mjs';
const stage='F:/VisibleMedicine/staging/20261023-forearm-website',site=stage+'/website',prep=json(stage+'/PREPARATION.json'),dir=stage+'/browser',files=new Map(),requests=[];assert(!fs.existsSync(dir));fs.mkdirSync(dir);for(const module of ['head-neck','shoulder','lower-limb','female-pelvis']){const root=site+'/public/atlas-runtime/'+module,m=json(root+'/manifest.json');assert.equal(m.sourceCommit,prep.atlasHead);for(const r of m.files){const file=root+'/'+r.path;assert.equal(hash(file),r.sha256);files.set('/atlas-runtime/'+module+'/'+r.path,file);}}
const sources={forearm:'/atlas-runtime/head-neck/index.html?region=forearm'};
const pages=new Map(Object.entries(sources).map(([name,src])=>['/'+name,'<!doctype html><html><head><title>Isolated Website '+name+' verification</title></head><body><p>Exact Website-exported '+name+' module · normal preview unchanged.</p><iframe title="Atlas test" style="width:1200px;height:800px" src="'+src+'"></iframe></body></html>']));
const server=http.createServer((req,res)=>{const url=new URL(req.url,'http://fixture.invalid'),file=files.get(url.pathname),page=pages.get(url.pathname);requests.push({at:new Date().toISOString(),path:url.pathname,method:req.method,registered:!!file||!!page});res.setHeader('Cache-Control','no-store');if(page&&req.method==='GET'){res.setHeader('Content-Type','text/html;charset=utf-8');res.end(page);return;}if(!file||req.method!=='GET'){res.writeHead(404);res.end('Not registered');return;}res.setHeader('Content-Type',({'.html':'text/html;charset=utf-8','.js':'text/javascript;charset=utf-8','.css':'text/css;charset=utf-8','.json':'application/json','.glb':'model/gltf-binary','.txt':'text/plain'})[path.extname(file)]??'application/octet-stream');res.end(fs.readFileSync(file));});
function state(live){const p=json('CURRENT_CHECKPOINT.json');p.activeWork.current.activeExecutionSessions=p.activeWork.current.activeExecutionSessions.filter(r=>r.role!=='forearm-website-browser');if(live)p.activeWork.current.activeExecutionSessions.push({role:'forearm-website-browser',pid:process.pid,evidence:dir,previewChanged:false});const text=JSON.stringify(p,null,2)+'\n';assert(Buffer.byteLength(text)<65536);fs.writeFileSync('CURRENT_CHECKPOINT.json',text);}
server.listen(0,'127.0.0.1',()=>{const base='http://127.0.0.1:'+server.address().port;fs.writeFileSync(dir+'/STARTED.json',JSON.stringify({at:new Date().toISOString(),base,pid:process.pid,sourceCommit:prep.atlasHead,sources,actualEmittedWebsiteModules:true,applicationBytesUnmodified:true,authDataOrPrivateAssetsServed:false,previewChanged:false},null,2)+'\n',{flag:'wx'});state(true);console.log(JSON.stringify({base,pid:process.pid,quit:'q'}));});process.stdin.setEncoding('utf8');process.stdin.on('data',s=>{if(s.trim()==='q')server.close(()=>{fs.writeFileSync(dir+'/REQUESTS.json',JSON.stringify(requests,null,2)+'\n',{flag:'wx'});fs.writeFileSync(dir+'/TERMINAL.json',JSON.stringify({at:new Date().toISOString(),code:0,pid:process.pid,previewChanged:false},null,2)+'\n',{flag:'wx'});state(false);process.exit(0);});});
